-- Central de notificações: registro de avisos gerados pelo fluxo (complementação, entrega, troca de responsável, falha de integração).
CREATE TABLE IF NOT EXISTS notifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,quando VARCHAR(40) NOT NULL,tipo VARCHAR(30) NOT NULL,modulo VARCHAR(40) NOT NULL DEFAULT '',registro VARCHAR(40) NOT NULL DEFAULT '',destino VARCHAR(120) NOT NULL,titulo VARCHAR(200) NOT NULL,texto VARCHAR(500) NOT NULL DEFAULT '',lida TINYINT NOT NULL DEFAULT 0,KEY idx_notif_destino (destino,lida,id),KEY idx_notif_registro (modulo,registro)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
